package country

import (
	_ "embed"
	"sync"
)

// countriesJSON is generated by tools/gencountries.
//
//go:embed data/countries.json
var countriesJSON []byte

var loadDefault = sync.OnceValues(func() (*Store, error) {
	return Load(countriesJSON)
})

// Default returns the store built from the embedded data. It is parsed once
// per process.
func Default() (*Store, error) {
	return loadDefault()
}
